#include "DiagnosticsManager.h"
#include "App/AppPaths.h"
namespace vox { juce::String DiagnosticsManager::report(AudioEngine&e){auto*d=e.deviceManager().getCurrentAudioDevice();juce::String s="Modificador de Voz 1.0.0\nJUCE "+juce::SystemStats::getJUCEVersion()+"\nSO: "+juce::SystemStats::getOperatingSystemName()+"\nExecutável: "+juce::File::getSpecialLocation(juce::File::currentExecutableFile).getFullPathName()+"\nModo: "+(AppPaths::portable()?"portátil":"instalado")+"\n";if(!d)return s+"Áudio: nenhum dispositivo aberto\nErro: "+e.lastError();s<<"Entrada/saída: "<<d->getName()<<"\nSample rate: "<<d->getCurrentSampleRate()<<" Hz\nBuffer: "<<d->getCurrentBufferSizeSamples()<<" amostras\nCanais entrada/saída: "<<d->getActiveInputChannels().countNumberOfSetBits()<<"/"<<d->getActiveOutputChannels().countNumberOfSetBits()<<"\nLatência estimada: "<<juce::String(1000.0*(d->getInputLatencyInSamples()+d->getOutputLatencyInSamples()+d->getCurrentBufferSizeSamples())/d->getCurrentSampleRate(),1)<<" ms\nCPU DSP: "<<juce::String(e.cpuUsage()*100,1)<<"%\nUnderruns estimados: "<<(juce::int64)e.underruns()<<"\nPico entrada/saída: "<<juce::String(e.processor().inputPeak(),3)<<" / "<<juce::String(e.processor().outputPeak(),3)<<"\nErro recente: "<<e.lastError();return s;} }
